1	export type Cell = [x: number, y: number];
2	
3	function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
4	  return x === otherX && y === otherY;
5	}
6	
7	function isNeighbourOf(cell: Cell, candidate: Cell): boolean {
8	  const [x, y] = cell;
9	  const [candidateX, candidateY] = candidate;
10	  const isWithinOneStep =
11	    Math.abs(candidateX - x) <= 1 && Math.abs(candidateY - y) <= 1;
12	  return isWithinOneStep && !isSameCell(cell, candidate);
13	}
14	
15	function countNeighbours(liveCells: Cell[], cell: Cell): number {
16	  return liveCells.filter((candidate) => isNeighbourOf(cell, candidate)).length;
17	}
18	
19	function survives(cell: Cell, liveCells: Cell[]): boolean {
20	  return countNeighbours(liveCells, cell) === 2;
21	}
22	
23	function neighbourhoodOf([x, y]: Cell): Cell[] {
24	  const offsets = [-1, 0, 1];
25	  return offsets.flatMap((dx) =>
26	    offsets
27	      .filter((dy) => !(dx === 0 && dy === 0))
28	      .map((dy): Cell => [x + dx, y + dy]),
29	  );
30	}
31	
32	function isBorn(cell: Cell, liveCells: Cell[]): boolean {
33	  return (
34	    !liveCells.some((live) => isSameCell(live, cell)) &&
35	    countNeighbours(liveCells, cell) === 3
36	  );
37	}
38	
39	export function nextGeneration(liveCells: Cell[]): Cell[] {
40	  const survivors = liveCells.filter((cell) => survives(cell, liveCells));
41	  const births = liveCells
42	    .flatMap(neighbourhoodOf)
43	    .filter((cell) => isBorn(cell, liveCells))
44	    .filter(
45	      (cell, index, all) =>
46	        all.findIndex((other) => isSameCell(other, cell)) === index,
47	    );
48	  return [...survivors, ...births];
49	}
