function distinctCells(cells: Cell[]): Cell[] {
  return cells.filter(
    (cell, index) =>
      cells.findIndex((other) => isSameCell(other, cell)) === index,
  );
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const survivors = liveCells.filter((cell) => survives(cell, liveCells));
  const births = distinctCells(
    liveCells.flatMap(neighbourhoodOf).filter((cell) => isBorn(cell, liveCells)),
  );
  return [...survivors, ...births];
}
